import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);
  const processingRef = useRef(false);

  const [logs, setLogs] = useState([]);
  const [frameCount, setFrameCount] = useState(0);
  const [result, setResult] = useState(null);
  const [autoMode, setAutoMode] = useState(true);

  // ================= LOG SYSTEM =================
  const log = (step, message, data = null) => {
    const entry = {
      time: new Date().toLocaleTimeString(),
      step,
      message,
      data
    };
    setLogs(prev => [entry, ...prev.slice(0, 30)]);
    console.log(`[${step}]`, message, data || '');
  };

  // ================= CAMERA INIT =================
  useEffect(() => {
    const startCamera = async () => {
      try {
        log('CAMERA', 'Requesting camera...');
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'user' },
          audio: false
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = async () => {
            await videoRef.current.play();
            log('CAMERA', 'Camera started successfully');
          };
        }
      } catch (err) {
        log('CAMERA_ERROR', 'Camera access failed', err.message);
      }
    };
    startCamera();
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
      if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    };
  }, []);

  // ================= CAPTURE LOOP =================
  useEffect(() => {
    if (!autoMode) return;
    log('LOOP', 'Starting capture loop (1000ms)');
    intervalRef.current = setInterval(async () => {
      if (!videoRef.current || processingRef.current) return;
      try {
        processingRef.current = true;
        setFrameCount(prev => prev + 1);

        // STEP 1 - Capture frame
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 640;
        canvas.height = videoRef.current.videoHeight || 480;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);
        const imageBase64 = canvas.toDataURL('image/jpeg', 0.8);
        log('FRAME', 'Image captured', { size: imageBase64.length });

        // STEP 2 - Send to backend
        log('BACKEND', 'Sending image to backend...');
        const response = await attendanceAPI.recognize({ image_base64: imageBase64 });
        log('BACKEND', 'Response received from backend', response);

        const data = response?.data;
        if (!data) {
          log('ERROR', 'Empty backend response');
          return;
        }

        // STEP 3 - Backend confirms reception
        if (data.backend_received) {
          log('BACKEND', 'Backend confirmed image reception');
        }

        // STEP 4 - Pipeline processed
        if (data.pipeline_processed) {
          log('PIPELINE', 'Pipeline processed image', {
            success: data.success,
            student: data.student,
            confidence: data.confidence
          });
        }

        // STEP 5 - Result returned
        if (data.success && data.student) {
          log('RESULT', 'Face recognized successfully');
          setResult({
            success: true,
            student: data.student,
            confidence: data.confidence,
            time: new Date().toLocaleTimeString()
          });
        } else {
          log('RESULT', 'No match found or low confidence', data.message);
        }
      } catch (err) {
        log('ERROR', 'Request failed', err.message);
      } finally {
        processingRef.current = false;
      }
    }, 1000); // capture toutes les secondes pour debug
    return () => clearInterval(intervalRef.current);
  }, [autoMode]);

  return (
    <div style={{ display: 'flex', gap: 20, padding: 20 }}>
      {/* ================= CAMERA ================= */}
      <div style={{ flex: 1 }}>
        <h3>Camera</h3>
        <video ref={videoRef} autoPlay playsInline muted style={{ width: '100%', borderRadius: 10 }} />
        <div style={{ marginTop: 10 }}>
          <button onClick={() => setAutoMode(!autoMode)}>
            {autoMode ? 'Stop' : 'Start'}
          </button>
          <p>Frames: {frameCount}</p>
        </div>
        {result && (
          <div style={{ marginTop: 10, padding: 10, background: '#eee' }}>
            <h4>Result</h4>
            <p>Student: {result.student}</p>
            <p>Confidence: {result.confidence}</p>
            <p>Time: {result.time}</p>
          </div>
        )}
      </div>

      {/* ================= LOG PANEL ================= */}
      <div style={{ flex: 1, maxHeight: '80vh', overflow: 'auto' }}>
        <h3>Pipeline Debug Logs</h3>
        {logs.map((log, i) => (
          <div key={i} style={{
            marginBottom: 10,
            padding: 8,
            background: '#111',
            color: '#0f0',
            fontSize: 12,
            borderRadius: 6
          }}>
            <strong>[{log.step}]</strong> {log.message}
            <div style={{ color: '#aaa' }}>{log.time}</div>
            {log.data && (
              <pre style={{ fontSize: 10 }}>
                {JSON.stringify(log.data, null, 2)}
              </pre>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default CameraRecognition;
